contract InvMutTest {
    C c;

    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address recipient) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance > 0);

        uint beforeBalance = address(c).balance;
        uint recipientBefore = recipient.balance;
        c.withdrawAll(recipient); if (__ESBMC_reverted()) return;
        uint afterBalance = address(c).balance;
        uint recipientAfter = recipient.balance;

        assert(afterBalance == 0 && recipientAfter == recipientBefore + beforeBalance);
    }

    receive() external payable {}
}

